diff --git a/tests/bucket_test.go b/tests/bucket_test.go
new file mode 100644
index 0000000..e6385f7
--- /dev/null
+++ b/tests/bucket_test.go
@@ -0,0 +1,102 @@
+package tests
+
+import (
+	"errors"
+	"math"
+	"testing"
+	"time"
+
+	"example.com/ratelimit/ratelimit"
+)
+
+func TestBucketStartsFullAndRefills(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(2) {
+		t.Fatal("full bucket should allow capacity tokens")
+	}
+	if b.Allow(1) {
+		t.Fatal("empty bucket should refuse")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); got != 0.5 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+	c.Advance(10 * time.Second)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want capacity 2", got)
+	}
+}
+
+func TestBucketRefusesOversizedAndInvalidAllow(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	c.Advance(time.Hour)
+	if b.Allow(3) {
+		t.Fatal("n above capacity must be refused")
+	}
+	if b.Allow(0) || b.Allow(-1) || b.Allow(math.NaN()) {
+		t.Fatal("non-positive or NaN n must be refused")
+	}
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want 2 (nothing taken)", got)
+	}
+}
+
+func TestBucketNoPartialConsumption(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(3, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(2) {
+		t.Fatal("2 of 3 should be allowed")
+	}
+	if b.Allow(2) {
+		t.Fatal("2 with 1 available should be refused")
+	}
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens() = %v, want 1 (refused call takes nothing)", got)
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(1, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(1) {
+		t.Fatal("first take should succeed")
+	}
+	c.Advance(-time.Second)
+	if got := b.Tokens(); got != 0 {
+		t.Fatalf("Tokens() = %v, want 0 when clock went backwards", got)
+	}
+	c.Advance(2 * time.Second) // back to 1s after the original reference
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("Tokens() = %v, want 1 once clock passes latest time seen", got)
+	}
+}
+
+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct{ capacity, refill float64 }{
+		{0, 1}, {-1, 1}, {math.NaN(), 1}, {math.Inf(1), 1},
+		{1, 0}, {1, -1}, {1, math.NaN()}, {1, math.Inf(1)},
+	}
+	for _, tc := range bad {
+		if _, err := ratelimit.NewBucket(tc.capacity, tc.refill, c.Now); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("NewBucket(%v, %v): err = %v, want ErrInvalidConfig", tc.capacity, tc.refill, err)
+		}
+	}
+	if _, err := ratelimit.NewBucket(1, 1, nil); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+		t.Fatalf("nil now: err = %v, want ErrInvalidConfig", err)
+	}
+}

diff --git a/sched/plan_test.go b/sched/plan_test.go
new file mode 100644
index 0000000..f870d32
--- /dev/null
+++ b/sched/plan_test.go
@@ -0,0 +1,135 @@
+package sched
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+	"strconv"
+	"testing"
+	"time"
+)
+
+func TestPlanBatches(t *testing.T) {
+	got, err := Plan(map[string][]string{"a": {"b", "c", "b"}, "b": nil, "c": {"b"}, "d": {}})
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := [][]string{{"b", "d"}, {"c"}, {"a"}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Plan = %v, want %v", got, want)
+	}
+	empty, err := Plan(nil)
+	if err != nil || empty == nil || len(empty) != 0 {
+		t.Fatalf("Plan(nil) = %v, %v", empty, err)
+	}
+}
+
+func TestPlanUnknownBeforeCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{"x": {"y"}, "y": {"x"}, "q": {"zz", "aa"}, "r": {"nope"}})
+	var ue *UnknownDepError
+	if !errors.As(err, &ue) || ue.Task != "q" || ue.Dep != "aa" {
+		t.Fatalf("err = %v", err)
+	}
+	if ue.Error() != fmt.Sprintf("task %q depends on unknown task %q", "q", "aa") {
+		t.Fatalf("message = %q", ue.Error())
+	}
+}
+
+func TestPlanCanonicalCycle(t *testing.T) {
+	_, err := Plan(map[string][]string{"p": {"r", "q"}, "q": {"s"}, "s": {"p"}, "r": {"p"}})
+	var ce *CycleError
+	if !errors.As(err, &ce) {
+		t.Fatalf("err = %v", err)
+	}
+	want := []string{"p", "q", "s", "p"}
+	if !reflect.DeepEqual(ce.Path, want) {
+		t.Fatalf("Path = %v, want %v", ce.Path, want)
+	}
+	_, err = Plan(map[string][]string{"b": {"b"}})
+	if err.Error() != "dependency cycle: b -> b" {
+		t.Fatalf("self cycle = %q", err.Error())
+	}
+}
+
+func TestSimulate(t *testing.T) {
+	tasks := map[string]Task{
+		"a": {Duration: 3},
+		"b": {Deps: []string{"a"}, Duration: 2},
+		"c": {Duration: 4, Priority: 1},
+		"d": {Deps: []string{"b", "c"}, Duration: 1},
+	}
+	s, err := Simulate(tasks, 2)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if s.Makespan != 6 {
+		t.Fatalf("Makespan = %d", s.Makespan)
+	}
+	if got := s.Slots["c"]; got != (Slot{Start: 0, End: 4, Worker: 0}) {
+		t.Fatalf("c slot = %+v", got)
+	}
+	if got := s.Slots["a"]; got != (Slot{Start: 0, End: 3, Worker: 1}) {
+		t.Fatalf("a slot = %+v", got)
+	}
+	if want := []string{"a", "b", "d"}; !reflect.DeepEqual(s.CriticalPath, want) {
+		t.Fatalf("CriticalPath = %v, want %v", s.CriticalPath, want)
+	}
+	if _, err := Simulate(tasks, 0); !errors.Is(err, ErrNoWorkers) {
+		t.Fatalf("err = %v", err)
+	}
+	_, err = Simulate(map[string]Task{"z": {Duration: 0}, "y": {Duration: -1}}, 1)
+	var de *InvalidDurationError
+	if !errors.As(err, &de) || de.Task != "y" {
+		t.Fatalf("err = %v", err)
+	}
+	s, err = Simulate(nil, 1)
+	if err != nil || s.Slots == nil || s.CriticalPath == nil || s.Makespan != 0 {
+		t.Fatalf("empty = %+v, %v", s, err)
+	}
+}
+
+func TestScale(t *testing.T) {
+	const n = 200000
+	chain := make(map[string][]string, n)
+	for i := 0; i < n; i++ {
+		var deps []string
+		for j := 1; j <= 5 && i-j >= 0; j++ {
+			if j == 1 || i%3 == 0 {
+				deps = append(deps, "t"+strconv.Itoa(i-j))
+			}
+		}
+		chain["t"+strconv.Itoa(i)] = deps
+	}
+	start := time.Now()
+	if _, err := Plan(chain); err != nil {
+		t.Fatal(err)
+	}
+	tasks := make(map[string]Task, n)
+	for k, v := range chain {
+		tasks[k] = Task{Deps: v, Duration: 1 + len(k)%5}
+	}
+	if _, err := Simulate(tasks, 8); err != nil {
+		t.Fatal(err)
+	}
+	if d := time.Since(start); d > 4*time.Second {
+		t.Fatalf("too slow: %v", d)
+	}
+
+	ring := make(map[string][]string, n)
+	for i := 0; i < 100000; i++ {
+		ring["r"+strconv.Itoa(i)] = []string{"r" + strconv.Itoa((i+1)%100000)}
+	}
+	for i := 0; i < 100000; i++ {
+		ring["c"+strconv.Itoa(i)] = []string{"c" + strconv.Itoa(i-1)}
+	}
+	ring["c0"] = []string{"r0"}
+	start = time.Now()
+	_, err := Plan(ring)
+	var ce *CycleError
+	if !errors.As(err, &ce) || len(ce.Path) != 100001 {
+		t.Fatalf("ring err len = %v", err)
+	}
+	if d := time.Since(start); d > 2*time.Second {
+		t.Fatalf("ring cycle too slow: %v", d)
+	}
+}

