+package tests
+
+import (
+	"reflect"
+	"testing"
+
+	"example.com/wordfreq/wordfreq"
+)
+
+func TestTokenizeApostropheAndPunctuationRules(t *testing.T) {
+	got := wordfreq.Tokenize("'tis dogs' don't rock'n'roll well-known end. ÉCOLE \"x\"")
+	want := []string{"tis", "dogs", "don't", "rock'n'roll", "well", "known", "end", "école", "x"}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("Tokenize = %q, want %q", got, want)
+	}
+	if got := wordfreq.Tokenize("  '' ,, "); len(got) != 0 {
+		t.Fatalf("Tokenize of no-word text = %q, want empty", got)
+	}
+}
+
+func TestTopNTiesAndEdgeCases(t *testing.T) {
+	got := wordfreq.TopN("end. end Don't don't zeta alpha", 10)
+	want := []wordfreq.WordCount{{Word: "don't", Count: 2}, {Word: "end", Count: 2}, {Word: "alpha", Count: 1}, {Word: "zeta", Count: 1}}
+	if !reflect.DeepEqual(got, want) {
+		t.Fatalf("TopN = %v, want %v", got, want)
+	}
+	if got := wordfreq.TopN("a b", -1); got == nil || len(got) != 0 {
+		t.Fatalf("TopN with negative n = %v, want empty non-nil", got)
+	}
+	if got := wordfreq.TopN("...", 3); got == nil || len(got) != 0 {
+		t.Fatalf("TopN with no words = %v, want empty non-nil", got)
+	}
+}

