+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(o(3), c(5));
+    assert_eq!(s.ranges(), vec![(c(1), o(3)), (o(3), c(5))]);
+}
+
+#[test]
+fn single_point_is_closed_pair() {
+    let mut s = IntervalSet::new();
+    s.insert(c(7), c(7));
+    assert_eq!(s.ranges(), vec![(c(7), c(7))]);
+    assert_eq!(s.measure(), 0);
+    assert!(!s.is_empty());
+}
+
+#[test]
+fn measure_sums_lengths_of_canonical_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(c(3), c(5));
+    assert_eq!(s.measure(), 4);
+
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.insert(c(10), c(10));
+    assert_eq!(s.measure(), 4);
+    assert_ne!(s.measure(), 5);
+}
+
+#[test]
+fn measure_does_not_overflow_for_extreme_endpoints() {
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    assert_eq!(s.measure(), u64::MAX as i128);
+
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(-1));
+    s.insert(c(0), c(i64::MAX));
+    assert_eq!(s.measure(), u64::MAX as i128 - 1);
+}
+
+#[test]
+fn extreme_endpoints_are_handled() {
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    assert!(s.contains(0.0));
+    assert!(s.contains(i64::MIN as f64));
+    assert_eq!(s.ranges(), vec![(c(i64::MIN), c(i64::MAX))]);
+    s.remove(o(i64::MIN), o(i64::MAX));
+    assert_eq!(
+        s.ranges(),
+        vec![(c(i64::MIN), c(i64::MIN)), (c(i64::MAX), c(i64::MAX))]
+    );
+    s.remove(c(i64::MIN), c(i64::MAX));
+    assert!(s.is_empty());
+    assert_eq!(
+        IntervalSet::new().complement(c(i64::MIN), c(i64::MAX)),
+        vec![(c(i64::MIN), c(i64::MAX))]
+    );
+}
+
+#[test]
+fn complement_flips_endpoints_at_window_edges() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    s.insert(o(6), c(8));
+    assert_eq!(
+        s.complement(c(0), c(10)),
+        vec![(c(0), o(2)), (c(4), c(6)), (o(8), c(10))]
+    );
+
+    let mut s = IntervalSet::new();
+    s.insert(o(1), o(5));
+    assert_eq!(
+        s.complement(c(1), c(5)),
+        vec![(c(1), c(1)), (c(5), c(5))]
+    );
+
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    assert_eq!(s.complement(c(2), c(4)), vec![(c(4), c(4))]);
+}
+
+#[test]
+fn complement_empty_when_window_empty_or_covered() {
+    let mut s = IntervalSet::new();
+    s.insert(c(0), c(10));
+    assert!(s.complement(c(0), c(10)).is_empty());
+    assert!(s.complement(o(1), o(5)).is_empty());
+    assert!(s.complement(c(5), o(5)).is_empty());
+    assert!(s.complement(c(6), c(2)).is_empty());
+    assert_eq!(
+        IntervalSet::new().complement(c(1), c(3)),
+        vec![(c(1), c(3))]
+    );
+}
+
+#[test]
+fn display_formats_canonical_form() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(o(4), c(5));
+    s.insert(c(7), c(7));
+    assert_eq!(s.to_string(), "{[1,3), (4,5], [7,7]}");
+
+    let mut s = IntervalSet::new();
+    s.insert(o(-3), c(0));
+    assert_eq!(s.to_string(), "{(-3,0]}");
+
+    assert_eq!(IntervalSet::new().to_string(), "{}");
+}
+
+#[test]
+fn workload_with_sweeping_inserts_and_removes_is_fast() {
+    let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        x ^= x << 13;
+        x ^= x >> 7;
+        x ^= x << 17;
+        x
+    };
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let base = 1_000_000_000 - i * 3000;
+        let jitter = (next() % 2001) as i64 - 1000;
+        let lo_pos = base + jitter;
+        let len = (next() % 1001) as i64;
+        let hi_pos = lo_pos + len;
+        let lo = if next() % 2 == 0 { c(lo_pos) } else { o(lo_pos) };
+        let hi = if next() % 2 == 0 { c(hi_pos) } else { o(hi_pos) };
+        s.insert(lo, hi);
+
+        let rm_pos = base + (next() % 2001) as i64 - 1000;
+        s.remove(c(rm_pos), c(rm_pos + (next() % 1001) as i64));
+
+        let probe = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(probe);
+    }
+    let elapsed = start.elapsed();
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
+    s.insert(c(-5), c(-5));
+    assert!(s.contains(-5.0));
+    assert!(!s.contains(-5.5));
+}

