diff --git a/tests/loki_wall_roman.rs b/tests/loki_wall_roman.rs
new file mode 100644
index 0000000..60eac1b
--- /dev/null
+++ b/tests/loki_wall_roman.rs
@@ -0,0 +1,100 @@
+use romankit::{from_roman, to_roman, RomanError};
+use std::collections::HashSet;
+
+fn canonical_set() -> HashSet<String> {
+    (1..=3999u32)
+        .map(|n| to_roman(n).expect("1..=3999 must be valid"))
+        .collect()
+}
+
+#[test]
+fn to_roman_rejects_zero_and_above_3999() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert_eq!(to_roman(1).ok().as_deref(), Some("I"));
+    assert_eq!(to_roman(3999).ok().as_deref(), Some("MMMCMXCIX"));
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert_ne!(from_roman("IV").ok(), Some(6));
+    assert_ne!(from_roman("XIX").ok(), Some(21));
+}
+
+#[test]
+fn round_trip_holds_for_every_valid_number() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).expect("valid range");
+        assert_eq!(from_roman(&s).ok(), Some(n));
+    }
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_forms() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "input {s}");
+    }
+    assert!(from_roman("IIII").is_err());
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(from_roman("").ok().is_none());
+}
+
+#[test]
+fn from_roman_reports_first_invalid_character() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IX "), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("AXQ"), Err(RomanError::InvalidChar('A'))));
+    assert!(matches!(from_roman("xIVQ"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    for s in ["MMMM", "MMMMM", "MMMMCM", "IIII", "IC"] {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)), "input {s}");
+    }
+    assert!(matches!(from_roman("MMMM"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_accepts_exactly_canonical_numerals() {
+    let canonical = canonical_set();
+    let alphabet = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    let mut candidates: Vec<String> = vec![String::new()];
+    for len in 1..=4usize {
+        let mut next = Vec::new();
+        for prefix in candidates.iter().filter(|c| c.len() == len - 1) {
+            for &ch in &alphabet {
+                let mut s = prefix.clone();
+                s.push(ch);
+                next.push(s);
+            }
+        }
+        candidates.extend(next);
+    }
+    for s in &candidates {
+        if s.is_empty() {
+            assert!(matches!(from_roman(s), Err(RomanError::Empty)));
+            continue;
+        }
+        match from_roman(s) {
+            Ok(n) => {
+                assert!(canonical.contains(s), "accepted non-canonical {s}");
+                assert_eq!(to_roman(n).ok().as_deref(), Some(s.as_str()));
+            }
+            Err(e) => {
+                assert!(!canonical.contains(s), "rejected canonical {s}");
+                assert!(
+                    matches!(e, RomanError::NonCanonical),
+                    "wrong error for {s}"
+                );
+            }
+        }
+    }
+}
