+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+const EPS: f64 = 1e-9;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < EPS
+}
+
+#[test]
+fn summary_reports_interpolated_p50_and_p90() {
+    let line = summary(&[1.0, 2.0, 3.0, 4.0]);
+    assert_eq!(line, "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(line, "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    let sorted = summary(&[1.0, 2.0, 3.0, 4.0]);
+    let shuffled = summary(&[3.0, 1.0, 4.0, 2.0]);
+    assert_eq!(shuffled, sorted);
+    assert_eq!(summary(&[4.0, 3.0, 2.0, 1.0]), sorted);
+}
+
+#[test]
+fn summary_of_empty_or_all_nan_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    let line = summary(&[1.0, f64::NAN, 3.0]);
+    assert_eq!(line, "n=2 mean=2.00 p50=2.00 p90=2.80");
+    assert!(!line.contains("NaN"));
+}
+
+#[test]
+fn count_returns_number_of_non_nan_values() {
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_eq!(count(&[f64::NAN, f64::NAN]), 0);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+}
