--- /dev/null
+++ b/tests/reservations.rs
@@ -0,0 +1,95 @@
+use stockkit::{Inventory, Order, ReservationId, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o-2")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("apple", 4)
+        .with_line("plum", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 5), ("pear".to_string(), 2)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let order = Order::new("o-3").with_line("apple", 4);
+    let id = inv.reserve(&order).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    assert_eq!(inv.available("plum"), 0);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 10);
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure_in_sku_order() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o-4")
+        .with_line("pear", 3)
+        .with_line("apple", 1)
+        .with_line("kiwi", 1);
+    // "apple" sorts before "kiwi" and "pear", and it is fine; "kiwi" is unknown.
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::UnknownSku("kiwi".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+
+    let order = Order::new("o-5").with_line("apple", 1).with_line("pear", 3);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "pear".to_string(),
+            requested: 3,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("apple"), 5);
+    assert_eq!(inv.available("pear"), 1);
+}
+
+#[test]
+fn commit_ships_units_and_keeps_available_unchanged() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o-6").with_line("apple", 3)).unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 7);
+    assert_eq!(inv.available("apple"), before);
+}
+
+#[test]
+fn release_and_commit_reject_inactive_ids() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o-7").with_line("apple", 1)).unwrap();
+    inv.release(id).unwrap();
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(
+        inv.commit(ReservationId(999)),
+        Err(ReserveError::UnknownReservation)
+    );
+}
+
+#[test]
+fn reservation_ids_are_never_reused() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let empty = Order::new("o-8");
+    let a = inv.reserve(&empty).unwrap();
+    let b = inv.reserve(&empty).unwrap();
+    assert_ne!(a, b);
+    inv.release(a).unwrap();
+    let c = inv.reserve(&empty).unwrap();
+    assert_ne!(c, a);
+    assert_ne!(c, b);
+}

