+test("compound durations add every segment", () => {
+  expect(parseDuration("1h30m")).toBe(5_400_000);
+  expect(parseDuration("2d4h")).toBe(187_200_000);
+  expect(parseDuration("1m30s")).toBe(90_000);
+  expect(parseDuration("1h30m15s500ms")).toBe(5_415_500);
+});
+
+test("ms is not read as minutes", () => {
+  expect(parseDuration("250ms")).toBe(250);
+  expect(parseDuration("250m")).toBe(15_000_000);
+});
+
+test("whitespace around and between segments is allowed", () => {
+  expect(parseDuration("  1h 30m  ")).toBe(5_400_000);
+  expect(parseDuration("1h\t30m")).toBe(5_400_000);
+});
+
+test("rejects blank input", () => {
+  expect(() => parseDuration("")).toThrow("invalid duration");
+  expect(() => parseDuration("   ")).toThrow("invalid duration");
+});
+
+test("rejects unknown units and trailing junk", () => {
+  expect(() => parseDuration("5w")).toThrow("invalid duration");
+  expect(() => parseDuration("10mx")).toThrow("invalid duration");
+  expect(() => parseDuration("1h30")).toThrow("invalid duration");
+  expect(() => parseDuration("1h30m junk")).toThrow("invalid duration");
+});
+
+test("rejects a bare number with no unit", () => {
+  expect(() => parseDuration("10")).toThrow("invalid duration");
+});
+
 test("loadJob converts the timeout", () => {
   expect(loadJob({ name: "nightly", timeout: "5m" }).timeoutMs).toBe(300_000);
 });

