+func TestBucketRejectsBadConfig(t *testing.T) {
+	c := newClock()
+	bad := []struct {
+		cap, rate float64
+		now       func() time.Time
+	}{
+		{0, 1, c.Now}, {-1, 1, c.Now}, {math.NaN(), 1, c.Now}, {math.Inf(1), 1, c.Now},
+		{1, 0, c.Now}, {1, -1, c.Now}, {1, math.NaN(), c.Now}, {1, math.Inf(1), c.Now},
+		{1, 1, nil},
+	}
+	for i, tc := range bad {
+		if _, err := ratelimit.NewBucket(tc.cap, tc.rate, tc.now); !errors.Is(err, ratelimit.ErrInvalidConfig) {
+			t.Fatalf("case %d: err = %v, want ErrInvalidConfig", i, err)
+		}
+	}
+}
+
+func TestBucketRefillAndLimits(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(2, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(2) {
+		t.Fatal("full bucket should allow 2 tokens")
+	}
+	if b.Allow(1) {
+		t.Fatal("empty bucket should refuse")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); math.Abs(got-0.5) > 1e-9 {
+		t.Fatalf("Tokens() = %v, want 0.5", got)
+	}
+	if b.Allow(1) {
+		t.Fatal("0.5 tokens should not allow 1")
+	}
+	c.Advance(time.Hour)
+	if got := b.Tokens(); got != 2 {
+		t.Fatalf("Tokens() = %v, want capacity 2", got)
+	}
+	if b.Allow(3) {
+		t.Fatal("n greater than capacity should be refused")
+	}
+	if b.Allow(0) || b.Allow(-1) || b.Allow(math.NaN()) {
+		t.Fatal("zero, negative and NaN n should be refused")
+	}
+}
+
+func TestBucketClockGoingBackwards(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(4, 1, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	b.Allow(4)
+	c.Advance(2 * time.Second)
+	if got := b.Tokens(); math.Abs(got-2) > 1e-9 {
+		t.Fatalf("Tokens() = %v, want 2", got)
+	}
+	c.t = c.t.Add(-time.Second) // clock goes back 1s: no refill
+	if got := b.Tokens(); math.Abs(got-2) > 1e-9 {
+		t.Fatalf("Tokens() after backwards clock = %v, want 2", got)
+	}
+	c.Advance(time.Second) // back to the latest seen time: still no refill
+	if got := b.Tokens(); math.Abs(got-2) > 1e-9 {
+		t.Fatalf("Tokens() at latest seen time = %v, want 2", got)
+	}
+	c.Advance(time.Second) // 1s past the latest seen time
+	if got := b.Tokens(); math.Abs(got-3) > 1e-9 {
+		t.Fatalf("Tokens() = %v, want 3", got)
+	}
+}

