--- /dev/null
+++ b/tests/loki_wall_intervals.rs
@@ -0,0 +1,203 @@
+use intervalkit::intervals::{Bound, IntervalSet};
+use std::time::Instant;
+
+fn c(v: i64) -> Bound {
+    Bound::Closed(v)
+}
+
+fn o(v: i64) -> Bound {
+    Bound::Open(v)
+}
+
+#[test]
+fn bound_accessors_report_value_and_kind() {
+    assert_eq!(c(7).value(), 7);
+    assert!(c(7).is_closed());
+    assert_eq!(o(-3).value(), -3);
+    assert!(!o(-3).is_closed());
+}
+
+#[test]
+fn empty_intervals_are_ignored_and_open_interval_is_not() {
+    let mut s = IntervalSet::new();
+    s.insert(o(2), o(2));
+    s.insert(c(2), o(2));
+    s.insert(o(2), c(2));
+    s.insert(c(3), c(2));
+    assert!(s.is_empty());
+    assert!(s.ranges().is_empty());
+    assert!(!s.contains(2.0));
+    assert_eq!(format!("{}", s), "{}");
+
+    let mut t = IntervalSet::new();
+    t.insert(o(2), o(3));
+    assert!(!t.is_empty());
+    assert!(t.contains(2.5));
+    assert!(!t.contains(2.0));
+    assert!(!t.contains(3.0));
+}
+
+#[test]
+fn single_point_is_closed_pair_with_zero_measure() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), c(2));
+    assert_eq!(s.ranges(), vec![(c(2), c(2))]);
+    assert!(s.contains(2.0));
+    assert!(!s.contains(2.5));
+    assert_eq!(s.measure(), 0);
+}
+
+#[test]
+fn touching_intervals_merge_only_when_union_is_single_interval() {
+    let mut a = IntervalSet::new();
+    a.insert(c(1), o(3));
+    a.insert(c(3), c(5));
+    assert_eq!(a.ranges(), vec![(c(1), c(5))]);
+
+    let mut b = IntervalSet::new();
+    b.insert(c(1), c(3));
+    b.insert(o(3), o(5));
+    assert_eq!(b.ranges(), vec![(c(1), o(5))]);
+
+    let mut d = IntervalSet::new();
+    d.insert(o(1), o(3));
+    d.insert(c(3), c(3));
+    assert_eq!(d.ranges(), vec![(o(1), c(3))]);
+
+    let mut e = IntervalSet::new();
+    e.insert(o(1), o(3));
+    e.insert(o(3), o(5));
+    assert_eq!(e.ranges(), vec![(o(1), o(3)), (o(3), o(5))]);
+    assert!(!e.contains(3.0));
+
+    let mut f = IntervalSet::new();
+    f.insert(c(1), o(3));
+    f.insert(o(3), c(5));
+    assert_eq!(f.ranges(), vec![(c(1), o(3)), (o(3), c(5))]);
+}
+
+#[test]
+fn remove_splits_stored_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), c(5));
+    s.remove(c(2), c(2));
+    assert_eq!(s.ranges(), vec![(c(1), o(2)), (o(2), c(5))]);
+    assert!(!s.contains(2.0));
+    assert!(s.contains(1.5));
+
+    let mut t = IntervalSet::new();
+    t.insert(c(1), c(5));
+    t.remove(o(2), o(4));
+    assert_eq!(t.ranges(), vec![(c(1), c(2)), (c(4), c(5))]);
+    assert!(t.contains(2.0));
+    assert!(!t.contains(3.0));
+
+    let mut u = IntervalSet::new();
+    u.insert(c(1), c(5));
+    u.remove(o(3), o(3));
+    assert_eq!(u.ranges(), vec![(c(1), c(5))]);
+    assert!(u.contains(3.0));
+}
+
+#[test]
+fn contains_respects_endpoint_kinds() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    assert!(s.contains(2.0));
+    assert!(s.contains(3.999));
+    assert!(!s.contains(4.0));
+    assert!(!s.contains(1.999));
+
+    let mut t = IntervalSet::new();
+    t.insert(o(2), c(4));
+    assert!(!t.contains(2.0));
+    assert!(t.contains(4.0));
+}
+
+#[test]
+fn measure_handles_full_i64_range_without_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    assert_eq!(s.measure(), 18446744073709551615i128);
+    assert!(s.contains(i64::MIN as f64));
+    assert!(s.contains(i64::MAX as f64));
+
+    let mut p = IntervalSet::new();
+    p.insert(c(i64::MIN), c(i64::MIN));
+    assert_eq!(p.measure(), 0);
+    assert!(p.contains(i64::MIN as f64));
+}
+
+#[test]
+fn remove_over_full_range_clears_without_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(c(i64::MIN), c(i64::MAX));
+    s.remove(c(i64::MIN), c(i64::MAX));
+    assert!(s.is_empty());
+    assert!(!s.contains(0.0));
+}
+
+#[test]
+fn complement_flips_endpoints_at_window_edges() {
+    let mut s = IntervalSet::new();
+    s.insert(c(2), o(4));
+    s.insert(o(6), c(8));
+    assert_eq!(
+        s.complement(c(0), c(10)),
+        vec![(c(0), o(2)), (c(4), c(6)), (o(8), c(10))]
+    );
+
+    let empty = IntervalSet::new();
+    assert_eq!(empty.complement(c(0), c(10)), vec![(c(0), c(10))]);
+
+    let mut full = IntervalSet::new();
+    full.insert(c(0), c(10));
+    assert!(full.complement(c(0), c(10)).is_empty());
+
+    assert!(empty.complement(o(5), o(5)).is_empty());
+}
+
+#[test]
+fn display_formats_canonical_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(c(1), o(3));
+    s.insert(o(4), c(5));
+    s.insert(c(7), c(7));
+    assert_eq!(format!("{}", s), "{[1,3), (4,5], [7,7]}");
+
+    let mut t = IntervalSet::new();
+    t.insert(o(-3), c(0));
+    assert_eq!(format!("{}", t), "{(-3,0]}");
+}
+
+#[test]
+fn sweep_workload_finishes_quickly_and_stays_correct() {
+    let mut state: u64 = 0x9E37_79B9_7F4A_7C15;
+    let mut next = move || {
+        state ^= state << 13;
+        state ^= state >> 7;
+        state ^= state << 17;
+        state
+    };
+
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    let mut hits = 0u64;
+    for i in 0..300_000i64 {
+        let jitter = (next() % 2_000) as i64 - 1_000;
+        let pos = 1_000_000_000i64 - i * 3_333 + jitter;
+        let len = (next() % 1_001) as i64;
+        s.insert(c(pos), c(pos + len));
+        let r = (next() % 1_000_000_001) as f64;
+        if s.contains(r) {
+            hits += 1;
+        }
+        let rpos = 1_000_000_000i64 - i * 3_333 + (next() % 500) as i64;
+        s.remove(c(rpos), c(rpos));
+    }
+    let elapsed = start.elapsed();
+    assert!(elapsed.as_secs_f64() < 3.0, "took {:?}", elapsed);
+    assert!(!s.is_empty());
+    assert!(s.measure() >= 0);
+    let _ = hits;
+}

