+
+#[test]
+fn from_roman_handles_subtractive_endings() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert!(matches!(from_roman("IIII"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_parses_xix_as_nineteen() {
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert!(matches!(from_roman("XIXI"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical_junk() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "{s}");
+    }
+    assert_eq!(from_roman("XIV").ok(), Some(14));
+}
+
+#[test]
+fn from_roman_rejects_empty_string() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert_eq!(from_roman("I").ok(), Some(1));
+}
+
+#[test]
+fn from_roman_rejects_lowercase_as_invalid_char() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert_eq!(from_roman("XIV").ok(), Some(14));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_char_before_noncanonical() {
+    assert!(matches!(from_roman("I x"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("IIIIZ"), Err(RomanError::InvalidChar('Z'))));
+    assert!(matches!(from_roman("IVx"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IIII"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn to_roman_rejects_zero_and_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert_eq!(to_roman(1).ok().as_deref(), Some("I"));
+}
+
+#[test]
+fn to_roman_produces_canonical_bounds() {
+    assert_eq!(to_roman(1).ok().as_deref(), Some("I"));
+    assert_eq!(to_roman(3999).ok().as_deref(), Some("MMMCMXCIX"));
+    assert!(!matches!(to_roman(3999), Err(RomanError::OutOfRange)));
+}
+
+#[test]
+fn round_trip_holds_for_full_valid_range() {
+    for n in 1..=3999u32 {
+        let s = to_roman(n).unwrap();
+        assert_eq!(from_roman(&s).ok(), Some(n), "{s}");
+    }
+    assert!(matches!(from_roman("MMMM"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_accepts_exactly_canonical_forms() {
+    let mut canonical: HashMap<String, u32> = HashMap::new();
+    for n in 1..=3999u32 {
+        canonical.insert(to_roman(n).unwrap(), n);
+    }
+    let alphabet = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    let mut candidates: Vec<String> = vec![String::new()];
+    for _ in 0..4 {
+        let mut next = Vec::new();
+        for prefix in &candidates {
+            for c in alphabet {
+                let mut s = prefix.clone();
+                s.push(c);
+                next.push(s);
+            }
+        }
+        candidates.extend(next);
+    }
+    candidates.retain(|s| !s.is_empty());
+    for s in &candidates {
+        match canonical.get(s) {
+            Some(&want) => assert_eq!(from_roman(s).ok(), Some(want), "{s}"),
+            None => assert!(matches!(from_roman(s), Err(RomanError::NonCanonical)), "{s}"),
+        }
+    }
+    assert!(matches!(from_roman("IIV"), Err(RomanError::NonCanonical)));
+}
+
+#[test]
+fn from_roman_never_reports_out_of_range() {
+    for s in ["MMMM", "MMMMCMXCIX", "IIII", "IC", "VX", "XM", "M", "MMMCMXCIX"] {
+        assert!(!matches!(from_roman(s), Err(RomanError::OutOfRange)), "{s}");
+    }
+    assert!(matches!(from_roman("MMMM"), Err(RomanError::NonCanonical)));
+}
