+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[2.0, 4.0, 1.0, 3.0]), summary(&[1.0, 2.0, 3.0, 4.0]));
+}
+
+#[test]
+fn summary_empty_and_all_nan_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+    assert_eq!(summary(&[NAN, NAN]), "n=0");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, NAN, 3.0, 4.0]), "n=3 mean=2.67 p50=3.00 p90=3.80");
+    assert!(!summary(&[1.0, NAN, 3.0, 4.0]).contains("NaN"));
+}
+
+#[test]
+fn count_counts_only_non_nan() {
+    assert_eq!(count(&[1.0, NAN, 3.0]), 2);
+    assert_eq!(count(&[NAN, NAN]), 0);
+    assert_ne!(count(&[1.0, NAN, 3.0]), 3);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_empty() {
+    assert_eq!(mean(&[1.0, NAN, 3.0]), Some(2.0));
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[NAN]), None);
+    assert!(mean(&[1.0, NAN]).map_or(true, |m| !m.is_nan()));
+}
+
+#[test]
+fn median_is_percentile_50() {
+    assert_eq!(median(&[1.0, 2.0, 3.0, 4.0]), Some(2.5));
+    assert_eq!(median(&[5.0, 1.0, 3.0]), Some(3.0));
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[NAN]), None);
+    assert_eq!(median(&[NAN, 1.0, 3.0]), Some(2.0));
+}
+
+#[test]
+fn percentile_none_for_invalid_p() {
+    let v = [1.0, 2.0, 3.0];
+    assert_eq!(percentile(&v, NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+    assert_eq!(percentile(&v, 0.0), Some(1.0));
+    assert_eq!(percentile(&v, 100.0), Some(3.0));
+}
+
+#[test]
+fn percentile_none_when_no_non_nan_values() {
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[NAN, NAN], 50.0), None);
+    assert_eq!(percentile(&[NAN, 1.0, 2.0, 3.0], 100.0), Some(3.0));
+}
+
+#[test]
+fn percentile_uses_linear_interpolation() {
+    let v = [10.0, 20.0, 30.0];
+    assert!(close(percentile(&v, 25.0).unwrap(), 15.0));
+    assert!(close(percentile(&v, 75.0).unwrap(), 25.0));
+    assert!(!close(percentile(&v, 25.0).unwrap(), 20.0));
+}
+
+#[test]
+fn percentile_is_order_independent_and_does_not_mutate_input() {
+    let v = vec![3.0, 1.0, 2.0];
+    assert_eq!(percentile(&v, 50.0), Some(2.0));
+    assert_eq!(v, vec![3.0, 1.0, 2.0]);
+    let sorted = vec![1.0, 2.0, 3.0];
+    assert_eq!(percentile(&v, 90.0), percentile(&sorted, 90.0));
+}
diff --git a/tests/stats_fixes.rs b/tests/stats_fixes.rs
