@@ -0,0 +1,47 @@
+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_interpolates_and_ignores_order() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+}
+
+#[test]
+fn empty_and_all_nan_are_undefined() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_eq!(summary(&[f64::NAN]), "n=0");
+    assert_eq!(mean(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+    assert_eq!(percentile(&[], 50.0), None);
+}
+
+#[test]
+fn nan_values_are_ignored() {
+    let v = [1.0, f64::NAN, 3.0];
+    assert_eq!(count(&v), 2);
+    assert!(close(mean(&v).unwrap(), 2.0));
+    assert!(close(median(&v).unwrap(), 2.0));
+    assert_eq!(summary(&v), "n=2 mean=2.00 p50=2.00 p90=2.80");
+}
+
+#[test]
+fn percentile_rejects_bad_p() {
+    let v = [1.0, 2.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+    assert!(close(percentile(&v, 0.0).unwrap(), 1.0));
+    assert!(close(percentile(&v, 100.0).unwrap(), 2.0));
+}
+
+#[test]
+fn percentile_does_not_mutate_input() {
+    let v = [3.0, 1.0, 2.0];
+    let _ = percentile(&v, 50.0);
+    assert_eq!(v, [3.0, 1.0, 2.0]);
+}

diff --git a/tests/reservations.rs b/tests/reservations.rs
new file mode 100644
index 0000000..1f7335d
--- /dev/null
+++ b/tests/reservations.rs
@@ -0,0 +1,98 @@
+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let order = Order::new("o").with_line("apple", 4);
+    inv.reserve(&order).unwrap();
+    assert_eq!(inv.available("apple"), 6);
+    assert_eq!(inv.on_hand("apple"), 10);
+    assert_eq!(inv.available("plum"), 0);
+}
+
+#[test]
+fn reserve_is_all_or_nothing_and_reports_first_failure() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o")
+        .with_line("apple", 2)
+        .with_line("pear", 2)
+        .with_line("plum", 1);
+    // Sorted order: apple, pear, plum. pear fails first.
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "pear".to_string(),
+            requested: 2,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("apple"), 5);
+
+    let unknown = Order::new("o2").with_line("plum", 1).with_line("apple", 1);
+    assert_eq!(
+        inv.reserve(&unknown),
+        Err(ReserveError::UnknownSku("plum".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+}
+
+#[test]
+fn zero_quantity_order_gets_fresh_empty_reservation() {
+    let mut inv = Inventory::new();
+    let a = inv.reserve(&Order::new("empty")).unwrap();
+    let b = inv.reserve(&Order::new("empty")).unwrap();
+    assert_ne!(a, b);
+    assert_eq!(inv.release(a), Ok(()));
+    assert_eq!(inv.release(a), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn release_frees_units_and_ids_are_not_reused() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 3);
+    let first = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    assert_eq!(inv.available("apple"), 0);
+    inv.release(first).unwrap();
+    assert_eq!(inv.available("apple"), 3);
+    assert_eq!(inv.on_hand("apple"), 3);
+    let second = inv.reserve(&Order::new("o").with_line("apple", 1)).unwrap();
+    assert_ne!(first, second);
+    assert_eq!(inv.commit(first), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn commit_drops_on_hand_and_keeps_available() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 10);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 6);
+    assert_eq!(inv.available("apple"), before);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn unknown_id_is_rejected() {
+    let mut inv = Inventory::new();
+    let id = stockkit::ReservationId(42);
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+}

