diff --git a/test/cron.test.ts b/test/cron.test.ts
new file mode 100644
index 0000000..4fb831f
--- /dev/null
+++ b/test/cron.test.ts
@@ -0,0 +1,88 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("steps and lists", () => {
+  expect(nextRun("*/15 * * * *", at("2026-01-01T00:07:30Z"))).toEqual(at("2026-01-01T00:15:00Z"));
+  expect(nextRun("10-50/20 * * * *", at("2026-01-01T00:10:00Z"))).toEqual(at("2026-01-01T00:30:00Z"));
+  expect(nextRun("0,30 9 * * *", at("2026-01-01T09:00:00Z"))).toEqual(at("2026-01-01T09:30:00Z"));
+});
+
+test("does not modify from and drops seconds", () => {
+  const from = at("2026-01-01T00:00:30Z");
+  expect(nextRun("* * * * *", from)).toEqual(at("2026-01-01T00:01:00Z"));
+  expect(from.toISOString()).toBe("2026-01-01T00:00:30.000Z");
+});
+
+test("names are case-insensitive in month and weekday fields", () => {
+  expect(nextRun("0 0 1 jan,Jul *", at("2026-01-02T00:00:00Z"))).toEqual(at("2026-07-01T00:00:00Z"));
+  expect(nextRun("0 0 * * mon-fri", at("2026-01-03T00:00:00Z"))).toEqual(at("2026-01-05T00:00:00Z"));
+});
+
+test("day-of-month and day-of-week OR rule", () => {
+  // Last day of month OR Monday.
+  expect(nextRun("0 0 L * 1", at("2026-01-31T12:00:00Z"))).toEqual(at("2026-02-02T00:00:00Z"));
+  // Last Friday of February only.
+  expect(nextRun("0 0 * 2 5L", at("2026-01-01T00:00:00Z"))).toEqual(at("2026-02-27T00:00:00Z"));
+});
+
+test("L, LW and nW specials", () => {
+  expect(nextRun("0 0 LW 2 *", at("2026-01-01T00:00:00Z"))).toEqual(at("2026-02-27T00:00:00Z"));
+  // Feb 15 2026 is a Sunday, so Monday the 16th.
+  expect(nextRun("0 0 15W 2 *", at("2026-01-01T00:00:00Z"))).toEqual(at("2026-02-16T00:00:00Z"));
+  expect(() => nextRun("0 0 31W 2 *", at("2026-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("nth and last weekday specials", () => {
+  expect(nextRun("0 0 * * 5#3", at("2026-01-01T00:00:00Z"))).toEqual(at("2026-01-16T00:00:00Z"));
+  expect(nextRun("0 0 * * FRI#5", at("2026-01-01T00:00:00Z"))).toEqual(at("2026-01-30T00:00:00Z"));
+  // No fifth Friday in Feb, Mar or Apr 2026; May 29 is the fifth.
+  expect(nextRun("0 0 * * 5#5", at("2026-02-01T00:00:00Z"))).toEqual(at("2026-05-29T00:00:00Z"));
+});
+
+test("leap day and aliases", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-01-01T00:00:00Z"))).toEqual(at("2028-02-29T00:00:00Z"));
+  expect(nextRun("@HOURLY", at("2026-01-01T00:30:00Z"))).toEqual(at("2026-01-01T01:00:00Z"));
+  expect(nextRun("@daily", at("2026-01-01T10:00:00Z"))).toEqual(at("2026-01-02T00:00:00Z"));
+});
+
+test("throws for impossible schedules and invalid expressions", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2026-01-01T00:00:00Z"))).toThrow(CronError);
+  const invalid = [
+    "* * * *",
+    "60 * * * *",
+    "5/15 * * * *",
+    "*/0 * * * *",
+    "5-1 * * * *",
+    "1,,2 * * * *",
+    "JAN * * * *",
+    "* * * * 8#1",
+    "* * * * 5#0",
+    "* * * * 5#6",
+    "* * * * dW",
+    "* * * * 5L/2",
+    "0 0 1W-5 * *",
+    "0 0 L/2 * *",
+    "0 0 0W * *",
+    "@foo",
+    "@daily extra",
+  ];
+  for (const expr of invalid) {
+    expect(() => nextRun(expr, at("2026-01-01T00:00:00Z"))).toThrow(CronError);
+  }
+});
+
+test("averages well under 1 ms per call on rare schedules", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const started = performance.now();
+  for (let i = 0; i < 3000; i++) {
+    const from = new Date(Date.UTC(2000 + (i % 100), (i * 7) % 12, 1 + ((i * 13) % 28)));
+    try {
+      nextRun(schedules[i % schedules.length], from);
+    } catch (err) {
+      expect(err).toBeInstanceOf(CronError);
+    }
+  }
+  expect(performance.now() - started).toBeLessThan(2000);
+});

