+  expect(() => parseDuration("10x")).toThrow();
+  expect(() => parseDuration("10mx")).toThrow();
+  expect(() => parseDuration("1h30")).toThrow();
+  expect(() => parseDuration("10")).toThrow();
+  expect(() => parseDuration("h")).toThrow();
