+
+test("middle page returns the full page without dropping items", () => {
+  const p = paginate([1, 2, 3, 4, 5, 6], 2, 2);
+  expect(p.items).toEqual([3, 4]);
+  expect(p.hasNext).toBe(true);
+});
+
+test("final partial page is counted and returns the remainder", () => {
+  const p = paginate([1, 2, 3, 4, 5], 3, 2);
+  expect(p.items).toEqual([5]);
+  expect(p.totalPages).toBe(3);
+  expect(p.hasNext).toBe(false);
+});
+
+test("hasNext is true before the last page of a partial division", () => {
+  const p = paginate([1, 2, 3, 4, 5], 2, 2);
+  expect(p.items).toEqual([3, 4]);
+  expect(p.totalPages).toBe(3);
+  expect(p.hasNext).toBe(true);
+});
+
+test("page past the end returns an empty list", () => {
+  const p = paginate([1, 2, 3], 5, 2);
+  expect(p.items).toEqual([]);
+  expect(p.totalPages).toBe(2);
+  expect(p.hasNext).toBe(false);
+});
+
+test("empty input has zero total pages", () => {
+  const p = paginate([], 1, 10);
